// @generated by the slice schematic from its spec. Edit in place; reshape via the spec and --force.
export type HeroPowerClass =
  'Aerial' | 'Energy' | 'Psionic' | 'Tech' | 'Mutant' | 'Cosmic' | 'Enhanced';
export type HeroStatus = 'Active' | 'Injured' | 'Reserve' | 'MIA';
export type HeroClearance = 'Tier 1' | 'Tier 2' | 'Tier 3' | 'Tier 4' | 'Tier 5';

export interface Hero {
  readonly id: string;
  name: string;
  alias: string;
  powerClass: HeroPowerClass;
  power: number;
  status: HeroStatus;
  clearance: HeroClearance;
  notes: string;
  active: boolean;
  missions: number;
  successRate: number;
}
// @generated by the slice schematic from its spec. Edit in place; reshape via the spec and --force.
import { Injectable, signal } from '@angular/core';
import type { Hero } from './hero.model';
import type { HeroFormModel } from './hero.schema';
import { EXAMPLE_HEROES } from './hero-example-data';

@Injectable({ providedIn: 'root' })
export class HeroService {
  private readonly _heroes = signal<Hero[]>(EXAMPLE_HEROES);
  private readonly _nextId = signal(
    Math.max(0, ...EXAMPLE_HEROES.map((item) => parseInt(item.id, 10))) + 1,
